#!/usr/bin/env python3
"""Authored a156-a167 photonic component and fiber interface work packages.
All calculated specimens are hypothetical, never vendor qualification settings.
"""
import json,copy
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2]
P=ROOT/'public/academy/data'
CAT={c['id']:c for c in json.loads((P/'catalog.json').read_text())}
OLD=json.loads((P/'sources.json').read_text()); BYURL={s['url']:s['id'] for s in OLD}
SOURCES=[];REFS={};COURSES=[];PLACES=[];RELATED=[]
def bi(s):
 a=s.split('~');assert len(a)==2,s;return a
def source(key,title,publisher,url,scope):
 t,te=bi(title);v,ve=bi(scope);sid=BYURL.get(url,'v9bt-'+key)
 rec=dict(id=sid,title=t,titleEn=te,publisher=publisher,url=url,scope=v,scopeEn=ve,category='packaging',sourceType='primary',accessedAt='2026-10-14',imageReuse='link-only',imageReuseEn='Reference link only; no source illustration copied.')
 REFS[key]=rec
 if url not in BYURL:SOURCES.append(rec);BYURL[url]=sid
source('pi','多通道主動光學對準~Multichannel active photonic alignment','PI','https://www.pi-usa.us/en/products/more-products/fast-multi-channel-photonics-alignment-systems','原廠對準方法與設備能力；課程不採用宣傳速度作保證。~Vendor alignment methods and capabilities; advertised speeds are not course guarantees.')
source('vgroove','SOI 光耦合與整合 V 溝~SOI coupling with integrated V-grooves','Ghent University / research authors','https://www.photonics.intec.ugent.be/publications/publications.asp?ID=2437','CMOS 相容 V 溝被動定位的原始研究紀錄。~Original research record on CMOS-compatible V-groove passive registration.')
source('glass','雷射寫入玻璃中介層與被動纖耦合~Laser-written glass interposer and passive fiber coupling','Ghent University / research authors','https://biblio.ugent.be/publication/8703691','整合玻璃波導與 V 溝的原始封裝研究。~Original packaging research integrating glass waveguides and V-grooves.')
source('adhesive','OE188 光學平台黏著材料資料~OE188 optical-bench adhesive data','Epoxy Technology','https://products.meridianadhesives.com/storage/downloads/bx1rzao3ziuk2ssi3iyjz0f5g34mcifh/oe188.pdf','代表材料的原廠資料；不可外推為所有光纖膠的性質或固化配方。~Vendor data for one representative material, not properties or cure instructions for all optical adhesives.')
source('overlap','軸對稱 Gaussian 光耦合研究~Axisymmetric Gaussian coupling research','Optica / research authors','https://opg.optica.org/ao/abstract.cfm?uri=ao-43-30-5691','可讀摘要介紹重疊積分；課程的相同腰面簡化式自行推導，未宣稱讀取付費公式。~Accessible abstract introduces overlap integrals; the matched-waist reduced equation is independently derived, not copied from inaccessible full equations.')
source('psr','矽偏振分光旋轉器原始實驗~Silicon polarization splitter-rotator experiment','Optica / research authors','https://opg.optica.org/ol/abstract.cfm?uri=ol-41-10-2346','絕熱錐形、非對稱方向耦合器與 MMI 模態濾波的原始研究。~Original research combining an adiabatic taper, asymmetric directional coupler and MMI mode filter.')
source('mmi','MMI 多模干涉耦合器模型~Multimode-interference coupler model','Ansys Optics','https://optics.ansys.com/hc/en-us/articles/360042305194-Multi-Mode-Interference-MMI-Coupler','原廠模態傳輸與寬頻 S 參數示範。~Vendor modal-transmission and broadband S-parameter example.')
source('dc','倏逝波導耦合器~Evanescent waveguide couplers','Ansys Optics','https://optics.ansys.com/hc/en-us/articles/360042304694-Evanescent-waveguide-couplers','超模及耦合長度的原廠模型教學。~Vendor tutorial on supermodes and coupling length.')
source('mzi','MZI 相位到強度響應~MZI phase-to-intensity response','Ansys Optics','https://optics.ansys.com/hc/en-us/articles/360042327954-Calculating-modulation-response-MZM-example','有效折射率擾動、相位與干涉的原廠解析示例。~Vendor analytical example of effective-index perturbation, phase and interference.')
source('tw','行波 MZI 的多物理模型~Traveling-wave MZI multiphysics model','Ansys Optics','https://optics.ansys.com/hc/en-us/articles/360042328774-Traveling-Wave-Mach-Zehnder-Modulator','載子、光學與 RF 協同模擬；課程算例不等於此範例製程。~Carrier, optical and RF co-simulation; course exercises are not the example process.')
source('ring','微環設計與群折射率~Ring design and group index','Ansys Optics','https://optics.ansys.com/hc/en-us/articles/360042800293-Ring-resonator-getting-started-Design-and-initial-simulation','共振、FSR 與群折射率的原廠推導。~Vendor derivation of resonance, FSR and group index.')
source('pd','橫向 Ge-on-Si 光偵測器~Lateral Ge-on-Si photodetector','Ansys Optics','https://optics.ansys.com/hc/en-us/articles/360042828913-Germanium-on-Silicon-lateral-photodetector','光生成率、暗電流與載子輸運的多物理示例。~Multiphysics example of photogeneration, dark current and carrier transport.')
source('apd','雪崩光偵測器多物理模型~Avalanche photodetector multiphysics model','Ansys Optics','https://optics.ansys.com/hc/en-us/articles/360042454814-Avalanche-photodetector','吸收、增益、暗電流及電場的原廠模型示例。~Vendor example of absorption, gain, dark current and electric field.')
source('apd09','單晶 Ge/Si 雪崩光二極體研究~Monolithic Ge/Si avalanche photodiode research','Nature Photonics / research authors','https://www.nature.com/articles/nphoton.2008.247','2009 年原始 Ge/Si APD 實驗；所報性能不是本課假想器件的保證。~Original 2009 Ge/Si APD experiment; reported performance does not qualify the hypothetical course device.')
source('heater','熱調矽波導~Thermally tuned waveguide','Ansys Optics','https://optics.ansys.com/hc/en-us/articles/360042338014-Thermally-tuned-waveguide-FEEM','由溫度場轉至模態折射率的原廠示例。~Vendor example mapping temperature fields to modal index.')
source('thermal','分層結構熱失配~Thermal mismatch in layered structures','COMSOL','https://www.comsol.com/model/thermal-stresses-in-a-layered-plate-273','用於辨識自由膨脹、約束與歷史；不是特定光子封裝模型。~Distinguishes free expansion, constraint and history; not a model of a specific photonic package.')
source('aim','光子測試與封裝據點~Photonic test and packaging center','AIM Photonics','https://www.aimphotonics.com/tap','公開封裝與測試機構及代表地理定位。~Public packaging/testing institution and representative geographic reference.')
BASE=next(copy.deepcopy(c['place']) for c in json.loads((P/'course-places.json').read_text())['courses'] if c['courseId']=='silicon-photonics')
def add(n,focus,stages,example,boundary,refs,related,rows):
 cid='a'+str(n);f,fe=bi(focus);ex,exe=bi(example);lim,lime=bi(boundary);src=[REFS[x]['id'] for x in refs.split()]
 units=[[bi(v) for v in row.split('|')] for row in rows.strip().splitlines()];assert len(units)==12 and all(len(row)==4 for row in units),(cid,len(units))
 c=copy.deepcopy(CAT[cid]);c.update(status='guided',contentStatus='reviewable-educational-curriculum',curriculumVersion=9,depth=4,stepCount=24,estimatedMinutes=720,simulationOnly=True,languageCoverage=['zh-TW','en'],sourceIds=src,subcategory='photonics-coupling' if n<159 else 'photonic-devices')
 c.update(summary=f'以{f}為主軸，完成 4 階段、24 項模型與判讀作業；包含定量算例、量測基準、失效區分與封裝交接。',summaryEn=f'Four stages and 24 modeling/diagnostic work packages address {fe}, with quantitative examples, measurement references, failure discrimination and package handoff.',scope='公開原理與可重算假想算例；不是代工廠配方、設備設定或產品合格界限。代表照片與概念圖不能當作每一步的實物製程影像。',scopeEn='Public principles and reproducible hypothetical examples, not foundry recipes, tool settings or product acceptance limits. Representative photos and concept diagrams are not images of each actual process operation.')
 c['workedExample']=dict(title='可重算的教學算例',titleEn='Reproducible teaching example',text=ex,textEn=exe,assumptions=lim,assumptionsEn=lime,sourceScope='本算例數值自行設定；來源支援原理，不提供這組產品規格。',sourceScopeEn='Example values are independently chosen; sources support principles, not these product specifications.')
 st=[bi(x) for x in stages.split('|')];assert len(st)==4
 c['diagram']=dict(type='photonics',labels=[x[0] for x in st],labelsEn=[x[1] for x in st],original=True,notToScale=True);c['stages']=[]
 for si,(sz,se) in enumerate(st):
  stage=dict(id=f'{cid}-stage{si+1:02d}',order=si+1,title=sz,titleEn=se,steps=[])
  for j in range(3):
   u=si*3+j;(title,titleen),(principle,principleen),(diagnostic,diagnosticen),(myth,mythen)=units[u]
   nextmyth=units[(u+1)%12][3]
   for mode in range(2):
    seq=u*2+mode+1;sid=f'{cid}-v9-{seq:02d}';correct=[principle,principleen] if mode==0 else [diagnostic,diagnosticen]
    options=[correct,[myth,mythen],nextmyth];shift=seq%3;options=options[shift:]+options[:shift];answer=(3-shift)%3
    instruction=(f'先標出「{title}」的座標、光／電／熱輸入與輸出。{principle} 用至少兩個設計狀態比較本單元變數，寫出能被量測推翻的預測；在工作台依師傅示意判讀相關介面，保留假設與未知參數。' if mode==0 else f'保留上一作業的模型，執行下列資料判讀：{diagnostic} 將原始量、單位、量測參考面與重複性分欄記錄；比較預測與觀察，說明能排除「{myth}」的直接證據，再決定接受、重測或修模。')
    instructionen=(f'Mark the coordinates and optical/electrical/thermal inputs and outputs for {titleen.lower()}. {principleen} Compare at least two design states and write a prediction that measurement could falsify. Review the relevant interfaces with the mentor view and preserve assumptions and unknown parameters.' if mode==0 else f'Retain the previous model and perform this data review: {diagnosticen} Record raw values, units, reference planes and repeatability separately. Compare prediction with observation and identify direct evidence rejecting "{mythen}" before accepting, remeasuring or revising.')
    if u in (2,8):instruction+=' '+ex;instructionen+=' '+exe
    step=dict(id=sid,order=seq,sequence=seq,title=title+('：模型與設計' if mode==0 else '：量測與判別'),titleEn=titleen+(': model and design' if mode==0 else ': measurement and diagnosis'),objective=f'建立{title}的可驗證模型及適用邊界。' if mode==0 else f'用{title}的量測證據區分競爭解釋。',objectiveEn=f'Build a verifiable model and validity boundary for {titleen.lower()}.' if mode==0 else f'Use measurements of {titleen.lower()} to distinguish competing explanations.',instruction=instruction,instructionEn=instructionen,observation=diagnostic,observationEn=diagnosticen,failure=f'錯誤推論「{myth}」可能使本步驗收失真。若結果不符，先檢查量測基準及模型邊界，再按本步診斷量分離原因；不能只調參讓曲線重合。',failureEn=f'The incorrect inference "{mythen}" can invalidate acceptance. If results disagree, check references and model validity, then separate causes using this step’s diagnostic rather than merely fitting parameters.',check=f'提交{title}的變數表、兩種狀態與量測判別紀錄：{diagnostic} 寫明剩餘不確定度與不支持的結論。',checkEn=f'Submit variables, two states and a measurement-discrimination record for {titleen.lower()}: {diagnosticen} State remaining uncertainty and unsupported conclusions.',estimatedMinutes=30,sourceIds=src,simulationOnly=True,prerequisiteIds=[f'{cid}-v9-{seq-1:02d}'] if seq>1 else [],knowledge=[dict(id=sid+'-k1',title='機制與模型',titleEn='Mechanism and model',text=principle,textEn=principleen,sourceIds=src),dict(id=sid+'-k2',title='量測如何區分解釋',titleEn='Discriminating measurement',text=diagnostic+' 不可推成：'+myth,textEn=diagnosticen+' Do not infer: '+mythen,sourceIds=src),dict(id=sid+'-k3',title='定量算例與適用範圍',titleEn='Worked example and validity',text=ex+' '+lim,textEn=exe+' '+lime,sourceIds=src)],quiz=dict(question=f'就「{title}」而言，哪項'+('原理正確？' if mode==0 else '驗證最能支持本步判讀？'),questionEn=f'For {titleen.lower()}, which '+('principle is correct?' if mode==0 else 'verification best supports this review?'),options=[x[0] for x in options],optionsEn=[x[1] for x in options],answer=answer,explanation=correct[0]+' '+lim,explanationEn=correct[1]+' '+lime))
    stage['steps'].append(step)
  c['stages'].append(stage)
 COURSES.append(c)
 refrows=[dict(title=REFS[x]['title'],titleEn=REFS[x]['titleEn'],url=REFS[x]['url'],publisher=REFS[x]['publisher'],scope=REFS[x]['scope'],scopeEn=REFS[x]['scopeEn']) for x in refs.split()]
 PLACES.append(dict(courseId=cid,place=copy.deepcopy(BASE),summary=f'以公開光子研發與封裝機構為地理代表，討論{f}如何由單一元件走向可量測、可封裝的系統。地圖沿用本學院矽光子課程的代表據點，並非此技術唯一發源地或所有文獻實驗位置。',summaryEn=f'A public photonic research/packaging institution provides geographic context for translating {fe} from a component into a measurable packaged system. The map uses the academy’s silicon-photonics reference location, not the sole invention site or every cited laboratory.',history=[dict(year='研究脈絡',title='從元件演示到可重現介面',titleEn='From component demonstration to reproducible interfaces',text=f'公開研究與模擬教學逐步把{f}連到基準、容差與封裝驗證。本課沿此方法脈絡安排作業，不宣稱單一機構獨創整項技術。',textEn=f'Public research and simulation tutorials connect {fe} to reference conditions, tolerances and package validation. The course follows that methodological progression without assigning invention to one institution.'),dict(year='工程交接',title='跨元件與封裝的共同驗證',titleEn='Joint device and package verification',text='相同光學性能需在固定、溫變與電性連接之後重新檢查；原始研究結果與量產資格是不同證據層級。',textEn='Recheck optical behavior after attachment, temperature change and electrical connection; research results and production qualification are different evidence levels.')],references=refrows+[dict(title=REFS['aim']['title'],url=REFS['aim']['url'],publisher='AIM Photonics',scope=REFS['aim']['scope'],scopeEn=REFS['aim']['scopeEn'])]))
 rel=[]
 for rid,transfer,difference,practice in related:
  tr,tre=bi(transfer);di,die=bi(difference);acts=[bi(x) for x in practice.split('|')];assert len(acts)==3
  rel.append(dict(id=rid,title=CAT[rid]['title'],titleEn=CAT[rid]['titleEn'],why=tr,whyEn=tre,transfer=tr,transferEn=tre,difference=di,differenceEn=die,practice=[x[0] for x in acts],practiceEn=[x[1] for x in acts],referenceUrls=[r['url'] for r in refrows]))
 RELATED.append(dict(courseId=cid,overview='把同一物理量跨到另一個工法時，先核對幾何、材料與量測邊界。',overviewEn='When transferring a physical quantity to another process, first reconcile geometry, materials and measurement boundaries.',related=rel,references=refrows))
add(156,'多軸光纖陣列搜尋、功率正規化與固定後漂移~Multiaxis fiber-array search, normalized power and post-attach drift','基準與可觀測量~References and observables|多軸搜尋~Multiaxis search|陣列與固定~Arrays and attachment|量產判讀~Production evidence','假設兩個相同 Gaussian 模態的強度 1/e² 半徑 w=2 μm，橫向偏移 d=1 μm，η=exp[−(d/w)²]=0.7788，單一偏移損耗 1.086 dB。若 d 降到 0.5 μm，損耗為 0.271 dB；均未含角度、端面反射及模態尺寸差。~For identical Gaussian modes with 1/e² intensity radius w=2 μm and lateral offset d=1 μm, η=exp[−(d/w)²]=0.7788 and offset loss is 1.086 dB. Reducing d to 0.5 μm gives 0.271 dB, excluding angle, facet reflection and size mismatch.','功率最大化不是幾何位置校準；雷射漂移、偏振、探測器飽和和多通道權重都可能改變搜尋結果。~Power maximization is not geometric calibration; laser drift, polarization, detector saturation and channel weighting can alter the search.','pi overlap',[
('a157','座標、纖芯公差與耦合地圖可共用~Coordinates, core tolerances and coupling maps transfer','被動對準使用機械基準，主動對準必須有有效光訊號~Passive alignment uses mechanical datums; active alignment requires a valid optical signal','把主動最佳點轉成幾何基準~Translate an optical optimum to mechanical datums|加入纖芯偏心比較~Compare after adding core eccentricity|列出被動法不能補償的殘差~List residuals passive alignment cannot correct'),
('a158','固化位移可投影到已量測耦合地圖~Cure displacement can be projected onto measured coupling maps','搜尋最佳點不保證固化和釋放後位置保持~An alignment optimum does not guarantee retention after curing and release','保存固定前地圖~Save pre-attach maps|量固化位移~Measure cure shift|預測並核對損耗變化~Predict and check loss change')],r'''
定義光功率參考面~Define optical power reference planes|輸出讀值同時含雷射、纖線、耦合與晶片路徑；搜尋目標須先正規化。~Output includes source, fiber, coupling and chip paths; normalize the objective before searching.|使用分光參考同步記錄輸入與輸出，判別源漂移與耦合變化。~Record input reference and output together to separate source drift from coupling change.|輸出變亮一定表示位置更準~Higher output always means better position
校準座標與軸向~Calibrate coordinates and axes|平台軸和光學法線不一定重合；旋轉會在偏置中心產生平移。~Stage axes need not match optical normals; rotation around an offset pivot induces translation.|小幅移動每軸，建立位移方向與光功率梯度的對照。~Dither each axis to map physical direction and power gradient.|機台 X 軸永遠等於晶片橫向~Stage X always equals chip lateral direction
建立初始捕獲區~Establish initial capture range|粗搜尋只需找到可靠光訊號，步距過大可能跨越窄峰而誤判無光。~Coarse search finds a reliable signal; excessive spacing can skip a narrow peak.|比較兩種掃描間距與光訊號下限，記錄未捕獲區。~Compare two scan spacings and signal floors, recording uncaptured regions.|找不到峰即代表晶片失效~Failure to find a peak proves chip failure
區分位置與偏振~Separate position and polarization|偏振變化會改變耦合，若搜尋時偏振不穩定，功率梯度不再單純代表位置。~Polarization changes coupling; unstable polarization corrupts positional gradients.|固定位置掃偏振，再固定偏振掃位置，分離兩個響應。~Sweep polarization at fixed position, then position at fixed polarization.|偏振可以交由位置搜尋完全補償~Position search fully compensates polarization
辨識局部與全域峰~Distinguish local and global peaks|反射、旁瓣和散射路徑可產生局部峰，單次爬山不保證全域最優。~Reflections, sidelobes and scattering create local maxima; one hill climb need not find the global optimum.|由三個不同起點搜尋，核對峰位置及頻譜是否一致。~Search from three starting points and compare peak positions and spectra.|任何零梯度點都是最佳耦合~Every zero-gradient point is optimum coupling
處理耦合自由度~Handle coupled degrees of freedom|俯仰、偏航和軸向距離可能共同移動光斑；逐軸最佳化需檢查交互作用。~Pitch, yaw and axial distance jointly move the spot; sequential optimization needs interaction checks.|量位置與角度二維地圖，檢查等功率輪廓是否傾斜。~Measure a position-angle map and inspect tilted equal-power contours.|各軸個別最佳值必然組成共同最佳~Separate axis optima necessarily form a joint optimum
設定陣列目標函數~Set an array objective|最大總功率可能犧牲最差通道；量產目標要明定最小值、平均值或加權值。~Maximum total power can sacrifice the worst channel; state minimum, mean or weighted objectives.|以一強一弱通道比較總和最大與最差通道最大兩解。~Compare maximum sum and maximum worst-channel solutions for unequal channels.|總功率最大即每通道都最佳~Maximum total power means every channel is optimum
量測纖距與傾斜~Measure pitch and roll mismatch|旋轉能修正陣列斜率，不能消除纖距與局部芯偏心造成的非線性殘差。~Roll corrects array slope but not pitch or local core eccentricity residuals.|畫通道編號對最佳位置，分離共同偏移、斜率和局部殘差。~Plot optimum position by channel and separate offset, slope and local residuals.|旋轉陣列可消除任何纖芯偏差~Rotating an array removes every core error
驗算位置損耗預算~Calculate positional loss budget|耦合容差取決於模態半徑和損耗門檻，不能用平台解析度替代。~Tolerance depends on mode radius and loss allocation, not stage resolution alone.|重算 1.086 dB 範例，再由允許損耗反推位置範圍。~Recalculate 1.086 dB and invert the model for an allowed-loss window.|奈米解析度等於奈米絕對定位準確度~Nanometer resolution equals nanometer absolute accuracy
追蹤固化與釋放~Track cure and release|膠收縮與夾持卸載會把最佳位置移走，固化前最佳值不是最終交付值。~Cure shrinkage and fixture unloading shift the optimum; pre-cure performance is not final performance.|連續記錄固化、冷卻和釋放三段功率及平台位置。~Log power and position through cure, cooling and release.|只要固化前最佳就能直接出貨~A pre-cure optimum is sufficient for shipment
辨識量測飽和~Detect measurement saturation|探測器飽和會把峰頂壓平，錯誤停止條件可能將任意平台位置視為最優。~Detector saturation flattens peaks and can make arbitrary positions appear optimal.|降低輸入功率並重掃，檢查正規化峰形是否改變。~Reduce input power and rescan, checking normalized peak shape.|平坦峰頂一定表示容差寬~A flat peak always means broad tolerance
交付可重複定位結果~Deliver repeatable alignment results|定位重複性、固化穩定性與跨通道最差損耗應分開統計。~Alignment repeatability, cured stability and worst-channel loss need separate statistics.|重複卸載重裝並比較每通道分布，不只報一次最佳值。~Repeat unload/reload and compare channel distributions, not one best result.|單次最高功率足以代表組裝良率~One maximum-power result represents assembly yield
''')
add(157,'V 溝幾何基準、纖芯偏心與公差堆疊~V-groove datums, core eccentricity and tolerance stacks','幾何基準~Mechanical datums|公差堆疊~Tolerance stack|光學驗證~Optical verification|組裝與保持~Assembly and retention','假設三個獨立零均值位置標準差為 0.3、0.4、0.2 μm，合成 σ=√(0.3²+0.4²+0.2²)=0.539 μm；若另有 0.8 μm 系統偏差，它必須獨立保留，不能放進 RSS 後當作可抵消誤差。~Assume independent zero-mean position standard deviations 0.3, 0.4 and 0.2 μm: combined σ=0.539 μm. A separate 0.8 μm systematic bias must remain explicit; it is not a canceling random RSS term.','機械公差模型需有同一座標與相關性假設；V 溝可定位包層，不會自動量到纖芯和光學模態中心。~Mechanical tolerances need common coordinates and covariance assumptions; a V-groove locates cladding, not automatically the core or optical-mode center.','vgroove glass overlap',[
('a156','共同座標與耦合地圖可驗證被動定位殘差~Common coordinates and coupling maps verify passive-placement residuals','主動法以光訊號修正，純被動法不在組裝時找峰~Active alignment corrects by optical feedback; passive assembly does not search a peak','量機械預定位點~Measure mechanical placement|主動搜尋殘差~Actively find residual offset|拆解固定偏差與隨機誤差~Separate systematic and random error'),
('a155','邊緣展模可以放寬被動位置預算~Expanded edge modes can relax passive alignment budgets','波導展模仍需端面與角度管理~Mode expansion still needs facet and angle control','比較兩種模式半徑~Compare two mode radii|以同一位置散布算損耗~Calculate loss for the same offset spread|核對端面反射~Check facet reflection')],r'''
設定機械與光學基準~Set mechanical and optical datums|晶片邊緣不一定與波導端點共線；裝配需定義可量測的基準轉換。~The chip edge need not coincide with waveguide endpoints; assembly requires measurable datum transforms.|把圖面基準、視覺標記與模態中心標在同一圖上。~Mark drawing datums, vision marks and mode centers in one coordinate map.|晶片切邊就是光學中心的精確基準~A diced edge is an exact optical-center datum
解析 V 溝接觸~Analyze V-groove contact|纖維與兩側接觸決定高度，包層直徑和溝角誤差都會改變中心位置。~Two-sided contact sets height; cladding diameter and groove-angle errors both shift center.|用兩個不同直徑圓畫接觸位置，比較中心高度。~Draw contact for two fiber diameters and compare center height.|V 溝深度固定就代表纖芯高度固定~Fixed groove depth fixes core height
檢查纖芯偏心~Check core eccentricity|包層中心與纖芯中心的差屬光纖內部誤差，外形量測不能完全替代。~Core-to-cladding offset is an internal fiber error not fully captured by exterior metrology.|旋轉單根纖維，觀察最佳光學中心是否繞包層中心移動。~Rotate a fiber and observe whether its optical center moves around the cladding center.|包層圓度良好即可排除芯偏心~Good cladding roundness excludes core eccentricity
區分固定與隨機誤差~Separate systematic and random error|共同遮罩偏移或標尺偏差影響所有通道，不能假設以多通道平均消失。~Shared mask or scale bias affects every channel and need not average away.|用批次平均與批次內殘差分層統計位置。~Separate between-lot mean offsets from within-lot residuals.|通道越多共同偏差越小~More channels reduce common bias
傳播相關公差~Propagate correlated tolerances|RSS 適用獨立標準差；同一基準引起的共變異數可能增加或減少合成變異。~RSS assumes independence; shared-datum covariance can increase or reduce combined variation.|重算 0.539 μm 並加入一項正相關，說明結果方向。~Recalculate 0.539 μm and add positive correlation, explaining the trend.|所有公差都可不問相關直接平方和~All tolerances can be RSS-combined without correlations
管理接觸污染~Manage contact contamination|夾在接觸面的粒子會抬升纖維並改變姿態，黏著強度高也不能修正。~Contact particles lift and tilt fibers; strong adhesive cannot correct the geometry.|比較清潔前後的接觸點影像與光損耗。~Compare contact images and optical loss before and after cleaning.|膠很牢就不必管 V 溝底的粒子~Strong adhesive makes groove particles irrelevant
分配纖距公差~Allocate fiber-pitch tolerances|共同節距誤差隨通道距離累積；中心通道良好不能保證邊緣通道。~Common pitch error accumulates with channel distance; good center coupling does not qualify edge channels.|繪製通道序號對位置誤差並擬合斜率。~Plot position error by channel number and fit the slope.|只測中間纖芯足以驗證整排~Testing the middle core validates the entire array
設計止擋與間隙~Design stops and gaps|軸向止擋控制端面距離，但熱膨脹或過大預壓可能造成端面接觸損傷。~Axial stops control gaps, but expansion or excessive preload can damage contacting facets.|畫最小和最大間隙角點並確認沒有機械干涉。~Draw minimum/maximum gap corners and check mechanical interference.|間隙越小永遠越安全且低損耗~A smaller gap is always safer and lower loss
結合公差與光學損耗~Link tolerance to optical loss|位置分布經非線性耦合函數轉成損耗分布，平均位置不能直接映成平均效率。~A nonlinear coupling function converts offset to loss; mean position does not give mean efficiency.|將幾個偏移樣本各自轉換損耗，再與平均偏移算例比較。~Convert each offset sample to loss and compare with the mean-offset estimate.|平均偏移為零就保證平均損耗為零~Zero mean offset guarantees zero mean loss
評估蓋板與預壓~Assess lid and preload|壓住纖維只限制特定自由度；預壓不均可改變通道高度和玻璃應力。~A lid constrains selected degrees of freedom; uneven preload shifts heights and stresses glass.|在不同夾持條件比較每通道高度及損耗。~Compare channel heights and losses under different clamping states.|蓋板一壓所有自由度都完全固定~A lid fully constrains every degree of freedom
固定後溫度循環~Cycle temperature after attachment|玻璃、矽與膠的熱伸長差會改變被動基準，室溫合格不代表全溫範圍。~Glass, silicon and adhesive expansion alter passive datums; room-temperature success does not qualify the full range.|同步記錄溫度、位移與各通道損耗，區分可逆與殘留。~Log temperature, displacement and channel loss, separating reversible and residual changes.|室溫被動定位合格即不需熱測試~Room-temperature passive alignment removes the need for thermal testing
交付可製造性證據~Deliver manufacturability evidence|被動法的價值取決於公差鏈良率與檢查成本，不能只比較單次裝配速度。~Passive alignment value depends on tolerance-chain yield and inspection cost, not one assembly time.|比較跨批次合格比例與返工原因，標記未量測的公差。~Compare cross-lot pass fractions and rework causes, marking unmeasured tolerances.|被動定位必定比主動定位有更高良率~Passive alignment always yields better than active alignment
''')
add(158,'光纖膠固化收縮、熱失配與長期黏彈漂移~Fiber-adhesive cure shrinkage, thermal mismatch and viscoelastic drift','材料與配置~Materials and placement|固化與釋放~Cure and release|熱機光耦合~Thermo-optomechanical coupling|老化與交付~Aging and handoff','假設兩條自由路徑的 Δα=15 ppm/K、長度 L=4 mm、ΔT=60 K，自由伸長差 Δu=3.6 μm。若此差全部投影成相同 Gaussian 模態 w=3 μm 的橫向位移，損耗 4.343(3.6/3)²=6.25 dB；實際黏著結構需另解約束和位移方向，不能把 6.25 dB 當實測值。~For free paths with Δα=15 ppm/K, L=4 mm and ΔT=60 K, mismatch is 3.6 μm. If entirely projected laterally onto matched Gaussian modes with w=3 μm, loss is 4.343(3.6/3)²=6.25 dB. Real constraints and displacement direction require separate analysis; 6.25 dB is not measured performance.','體積收縮率不是線性收縮率；小且各向同性時線收縮約為體積收縮的三分之一，但受約束膠層不能直接套用自由收縮位移。~Volumetric shrinkage is not linear shrinkage; small isotropic free linear shrinkage is about one third of volume shrinkage, but constrained bond lines require a mechanical model.','adhesive thermal overlap',[
('a156','固化前後耦合地圖可分離搜尋與固定失效~Pre/post-cure maps separate alignment and attachment failure','膠老化與釋放漂移可能在搜尋結束後才出現~Aging and release shifts can occur after the alignment search','保存搜尋最佳點~Save the search optimum|逐段記錄固化漂移~Log cure-stage shifts|重定位判斷是否可恢復~Realign to assess recoverability'),
('a186','位移、應力與溫度場可輸入光學耦合模型~Displacement, stress and temperature feed optical-coupling models','黏著材料需時間與固化相依性，不宜只用常數彈性模數~Adhesives need time/cure dependence rather than only constant elasticity','建立膠層幾何~Define bond-line geometry|比較自由與受約束收縮~Compare free and constrained shrinkage|映射到光模態重疊~Map displacement to modal overlap')],r'''
選擇黏著位置~Choose adhesive placement|光路內膠需評估吸收與折射率，機械固定膠則仍會透過應力影響光路。~In-path adhesive needs absorption/index evaluation; out-of-path adhesive still affects optics through stress.|分開光學窗口與固定支點，標示每處膠的功能。~Separate optical windows and mechanical anchor points and label each adhesive role.|膠不在光路內就完全不影響光學~Out-of-path adhesive cannot affect optical behavior
核對材料資料條件~Check material-data conditions|CTE、模數和吸水性依溫度與固化程度改變，單一資料表典型值不是完整模型。~CTE, modulus and moisture uptake depend on temperature and cure; one typical value is not a full model.|把測試溫度、固化狀態和批次資料附到每個參數。~Attach temperature, cure state and lot to each parameter.|資料表典型值可用於所有固化狀態~Typical datasheet values apply to every cure state
區分體積與線收縮~Separate volume and linear shrinkage|自由各向同性小收縮的線應變約為體積率三分之一，受約束後則重新分配應力。~Free isotropic small linear shrinkage is about one third of volumetric shrinkage; constraints redistribute stress.|用立方體三方向縮短推導體積近似，再指出膠層約束。~Derive the volume approximation from three cube dimensions, then identify bond constraints.|1% 體積收縮就是每軸 1% 收縮~One-percent volume shrinkage means one percent on every axis
控制膠量與厚度~Control adhesive volume and thickness|膠量決定幾何及收縮力臂；平均厚度相同但形狀不對稱仍可產生旋轉。~Volume sets geometry and shrinkage lever arms; equal mean thickness with asymmetric shape can rotate parts.|比較對稱與單側膠點的位移方向，不只比較總膠量。~Compare displacement direction for symmetric and one-sided spots, not just volume.|相同膠量必然得到相同固化位移~Equal adhesive volume gives identical cure displacement
處理陰影與固化梯度~Handle shadowing and cure gradients|照射或溫度不均可造成反應程度梯度，外表面固化不能證明深處一致。~Illumination or temperature gradients cause conversion gradients; a cured exterior does not prove uniform bulk cure.|標示遮蔽區並比較局部材料或位移證據。~Map shadowed regions and compare local material or displacement evidence.|表面不黏代表整層完全固化~A non-tacky surface proves complete through-cure
記錄固化中光功率~Log optical power during curing|功率變化可能同時來自機械位移與膠折射率變化，要用位置和頻譜交叉判讀。~Power changes can combine motion and adhesive-index change; cross-check position and spectra.|同步量測位置、功率和溫度，標出不可由位移解釋的部分。~Record position, power and temperature together and mark unexplained residuals.|固化時功率變化只可能是收縮~Any cure-time power change must be shrinkage
比較釋放前後~Compare before and after fixture release|夾持工具可能暫時承受膠的內應力，移除工具後才出現彈性回復。~Fixtures may temporarily carry adhesive stress; springback appears after release.|將固化終點與卸載終點分開存檔，量同一自由度。~Archive cure completion and unloading separately using the same coordinates.|固化完成後夾具已不再影響位置~A fixture ceases to affect position once cure ends
計算熱失配投影~Calculate projected thermal mismatch|自由伸長差須經結構約束轉成位移向量，沿光軸與橫向誤差造成不同損耗。~Free mismatch must be transformed through constraints into a displacement vector; axial and lateral errors differ optically.|重算 3.6 μm，分別假設橫向及軸向投影，列需補的光學模型。~Recalculate 3.6 μm for lateral and axial projections and list additional optical models.|自由熱伸長差可直接當任意方向的光學偏移~Free expansion mismatch directly equals optical offset in any direction
辨識黏彈鬆弛~Identify viscoelastic relaxation|固定溫度下位置隨時間變化可能是鬆弛或蠕變，不能當成純粹可逆 CTE。~Time drift at fixed temperature may be relaxation or creep, not reversible CTE.|比較快慢熱掃描及等溫停留，追蹤遲滯與恢復。~Compare fast/slow thermal sweeps and isothermal dwell for hysteresis and recovery.|只要溫度固定位置就不會漂移~Position cannot drift at fixed temperature
隔離吸濕與熱效應~Separate moisture and thermal effects|吸水膨脹和界面弱化可能與熱失配耦合，乾熱與濕熱應分組。~Moisture swelling and interface weakening can couple to mismatch; separate dry and damp heat groups.|以配對樣品比較位移、損耗與界面影像。~Compare displacement, loss and interface images using matched groups.|所有濕熱損失都能靠冷卻恢復~Cooling reverses every damp-heat loss
建立光機失效判別~Discriminate optomechanical failure|若重新對準可恢復功率，優先檢查位置；不可恢復則還需查端面、材料或晶片劣化。~Recovery by realignment points to position; unrecovered loss also needs facet, material and chip checks.|先做低風險重定位診斷，再以影像或頻譜區分不可逆原因。~Use a low-risk realignment diagnosis, then images/spectra for irreversible mechanisms.|功率下降一定表示光纖已斷裂~Any power drop means a broken fiber
交付附著壽命證據~Deliver attachment-life evidence|初始插損、溫漂、殘留位移與老化條件是不同指標，需逐項報告。~Initial insertion loss, thermal drift, residual motion and aging conditions are distinct metrics.|保留每通道完整歷程與失效分類，避免只報平均。~Retain complete channel histories and failure classes rather than only averages.|初始耦合好即可推出長期可靠~Good initial coupling proves long-term reliability
''')
add(159,'偏振分光、旋轉與模態洩漏的獨立驗證~Independent verification of polarization splitting, rotation and modal leakage','端口與偏振~Ports and polarization|模態轉換~Mode conversion|串擾與頻寬~Crosstalk and bandwidth|系統整合~System integration','假想輸入 1 mW，目標端口功率 0.800 mW、洩漏端口 0.008 mW，端口消光比 10log10(0.800/0.008)=20 dB；兩端口總傳輸 0.808 對應 0.926 dB 損耗。消光比和總傳輸是不同量，尚未單獨量出偏振旋轉效率。~With hypothetical 1 mW input, 0.800 mW desired-port and 0.008 mW leakage power give 20 dB port extinction. Total transmission 0.808 implies 0.926 dB loss. Extinction and total transmission differ; rotation efficiency is not separately determined.','端口功率、偏振純度與高階模態含量必須分別定義；僅測總功率不能證明 TE/TM 旋轉。~Define port power, polarization purity and higher-order modal content separately; total power alone cannot prove TE/TM rotation.','psr dc mmi',[
('a161','非對稱超模與相位匹配可解釋選擇性轉移~Asymmetric supermodes and phase matching explain selective transfer','PSR 還需偏振／模態轉換，普通對稱耦合器僅轉移路徑~A PSR also converts polarization/mode; a symmetric coupler only transfers paths','比較 TE 與 TM 超模~Compare TE and TM supermodes|畫模式轉換順序~Draw the conversion order|量兩輸出偏振~Measure output polarizations'),
('a160','MMI 可作分光與模態選擇的一部分~MMIs can participate in splitting and mode selection','功率均分不等於偏振分離或旋轉~Equal splitting is not polarization separation or rotation','分析入射模式對稱性~Analyze incident-mode symmetry|比較兩種偏振輸出~Compare output for two polarizations|計算串擾與過量損耗~Calculate crosstalk and excess loss')],r'''
定義偏振端口~Define polarization-resolved ports|TE/TM 標籤以波導主電場和傳播軸定義，不能直接沿用光纖接頭的上下方向。~TE/TM labels depend on waveguide field and propagation axes, not simply connector orientation.|畫座標及每個端口允許的模式，核對注入模式名稱。~Draw coordinates and supported modes at each port and check excitation labels.|TE 就是任何照片中的水平方向~TE always means horizontal in a photograph
辨識分光與旋轉~Distinguish splitting from rotation|偏振分光把不同偏振送往不同路徑；旋轉則改變輸出模式偏振，兩功能可分段實作。~Splitting routes polarizations differently; rotation changes modal polarization, and the functions may occupy different sections.|分別列出 TE、TM 入射時的預期路徑與輸出模式。~List expected paths and output modes for TE and TM input separately.|兩個輸出端就足以證明偏振旋轉~Two output ports prove polarization rotation
建立完整功率表~Build a complete power table|目標端口與洩漏端口比值表示端口消光，未包含兩端同時損失的能量。~Desired-to-leakage ratio measures port extinction but misses loss common to both outputs.|重算 20 dB 及 0.926 dB，另留反射與輻射欄位。~Recalculate 20 dB and 0.926 dB and reserve reflected/radiated-power columns.|高消光比一定代表低插入損耗~High extinction always implies low insertion loss
追蹤絕熱模態演化~Track adiabatic modal evolution|緩變截面可使局部本徵模態連續演化，但需檢查與鄰近模態的間隔及耦合。~A slow taper can follow local eigenmodes, subject to mode separation and coupling.|沿長度畫有效折射率與場形，確認追蹤同一分支。~Plot effective indices and fields along the taper and track the same branch.|把錐形做長就保證任何模式完全轉換~Any sufficiently long taper guarantees perfect conversion
檢查非對稱耦合~Check asymmetric coupling|不同寬度波導可在指定模式間達到相位匹配，其他模式應保持失配。~Unequal waveguides can phase-match selected modes while leaving others mismatched.|同時掃兩種偏振的超模與功率轉移，找選擇性範圍。~Sweep supermodes and transfer for both polarizations to identify selectivity.|幾何不對稱必然產生理想偏振選擇~Geometric asymmetry guarantees ideal polarization selection
驗證高階模式濾除~Verify higher-order mode rejection|輸出總功率可能含不需要的高階模式；後段波導只支援基模時這部分會散失。~Output power may include unwanted higher modes that are lost in a following single-mode section.|作模態重疊分解，比較總通量和目標基模功率。~Decompose modal overlaps and compare total flux with desired fundamental power.|輸出通量等於可用基模功率~Output flux equals useful fundamental-mode power
量測偏振串擾~Measure polarization crosstalk|端口串擾與同端口偏振串擾是不同矩陣元素，需要偏振分析。~Port crosstalk and same-port polarization leakage are different matrix entries requiring polarization analysis.|在兩端口分別量 TE/TM，形成四項功率矩陣。~Measure TE/TM at both outputs to form a four-entry power matrix.|只量一個端口就能取得完整偏振矩陣~One port yields a complete polarization matrix
檢查波長與溫度~Check wavelength and temperature|相位匹配與模式混合隨波長和溫度變化，中心波長的消光不能代表全頻帶。~Phase matching and modal mixing vary with wavelength and temperature; center extinction does not qualify a band.|以固定入射偏振掃波長，再在不同溫度重複。~Sweep wavelength at fixed input polarization and repeat at different temperatures.|中心波長最佳即可推論整個通訊頻帶~Center-wavelength optimum qualifies the entire communication band
建立製程角點~Establish fabrication corners|寬度、厚度與蝕刻深度會一起改變模態條件，公差分析需保留相關性。~Width, thickness and etch depth jointly alter modes; tolerance analysis should retain correlations.|比較共同線寬偏移與兩臂差動偏移，找不同失效特徵。~Compare common width bias with differential arm bias and identify distinct signatures.|所有尺寸誤差只會等量增加損耗~Every dimensional error simply adds the same loss
核對反向傳輸~Check reverse transmission|線性互易元件有互易關係，但反向注入需對應正確端口與模式。~A linear reciprocal device obeys reciprocity only with correctly matched ports and modes.|以互換源與監測模式的測試核對 S 矩陣對稱關係。~Swap source and monitor modes to check S-matrix reciprocity.|反向從任意模式注入都會回到原模式~Any reverse input mode returns to the original mode
接合封裝偏振~Connect package polarization|纖維旋轉、應力雙折射與接頭重插會改變到達晶片的偏振，需獨立管理。~Fiber rotation, stress birefringence and reconnection alter polarization at the chip.|對比晶片端校準與外部接頭校準的消光值。~Compare extinction calibrated at the chip with that at an external connector.|外部偏振控制器讀值就是晶片入射偏振~External controller settings equal chip-input polarization
交付模式可追溯資料~Deliver mode-traceable data|PSR 模型應交付波長、溫度、端口、模式與相位慣例，避免只留單一最好消光比。~A PSR model needs wavelength, temperature, port, mode and phase conventions, not only best extinction.|用保存的多模 S 參數重建兩種入射偏振測試。~Reconstruct both input-polarization tests from saved multimode S-parameters.|一個最高消光數字就是完整元件模型~One peak extinction number is a complete device model
''')
add(160,'多模自成像、分光平衡與複數 S 參數~Multimode self-imaging, split balance and complex S-parameters','模態與自成像~Modes and self-imaging|幾何與收斂~Geometry and convergence|損耗與相位~Loss and phase|電路交接~Circuit handoff','假想 1 mW 輸入，兩輸出為 0.46、0.44 mW，總傳輸 0.90，過量損耗 −10log10(0.90)=0.458 dB；不平衡 10log10(0.46/0.44)=0.193 dB。理想均分每路 3.010 dB 是功率分配，不是 3.010 dB 的過量損耗。~With hypothetical 1 mW input and 0.46/0.44 mW outputs, total transmission is 0.90, excess loss 0.458 dB and imbalance 0.193 dB. The ideal 3.010 dB per branch is power division, not excess loss.','自成像近似只提供初估，需以足夠模態、正確端口和波長掃描驗證；數值收斂與實物校準是不同工作。~Self-imaging approximations give initial estimates; verify sufficient modes, correct ports and wavelength sweeps. Numerical convergence differs from physical calibration.','mmi mzi',[
('a161','均分器可用同一過量損耗和相位指標比較~Splitters share excess-loss and phase metrics','MMI 依多模干涉，方向耦合器依相鄰波導超模拍頻~An MMI uses multimode interference; a directional coupler uses adjacent-guide supermode beating','固定相同端口基準~Fix common port references|比較波長敏感度~Compare wavelength sensitivity|比較相位與公差~Compare phase and tolerances'),
('a162','MMI 複數輸出可用作 MZI 分合光模型~Complex MMI output feeds an MZI split/combine model','孤立 MMI 的功率平衡不保證整個 MZI 消光~Standalone MMI balance does not guarantee MZI extinction','輸入複數 S 參數~Import complex S-parameters|加入臂損耗差~Add arm-loss mismatch|預測干涉可見度~Predict fringe visibility')],r'''
建立模態疊加~Build a modal superposition|多模區內不同傳播常數累積相位差，在特定長度重建一個或多個像。~Modes with different propagation constants accumulate phase differences and recreate one or more images at selected lengths.|畫至少三個模態的相位演進，檢查輸出位置。~Plot phase evolution of at least three modes and inspect image positions.|MMI 就是把光當水平均分岔~An MMI simply splits light like a fluid junction
選擇輸入對稱性~Select input symmetry|中央與偏心注入激發不同模態組合，輸出像的數量和位置可改變。~Centered and offset inputs excite different mode sets, changing image count and position.|比較中心與偏移注入的場形及輸出平衡。~Compare fields and balance for centered and offset inputs.|輸入放哪裡都會得到相同輸出~Input position never changes outputs
區分分光與損耗~Separate division and loss|兩路相加才可估傳輸，單路約一半功率不能直接當作吸收。~Sum both outputs to estimate transmission; half power in one branch is not absorption.|重算 0.458 dB 過量損耗並核對兩路和。~Recalculate 0.458 dB excess loss and verify the output sum.|每路少一半代表元件吸收一半~Half power per branch means half is absorbed
設計輸入輸出錐形~Design interface tapers|錐形改善單模波導與多模區重疊，但過急變化仍會激發輻射或反射。~Tapers improve overlap between access guides and multimode regions, but abrupt transitions radiate or reflect.|分別掃錐形寬度和長度，保留回反與通量。~Sweep taper width and length independently, retaining reflection and flux.|只加錐形就能消除全部反射~Adding a taper removes every reflection
驗證模態數收斂~Verify mode-count convergence|EME 截斷過少模態會忽略界面場，導致虛假的高傳輸或錯誤相位。~Too few EME modes omit interface fields and can distort transmission or phase.|增加模態數直到功率和相位均穩定，而非只看一條曲線。~Increase mode count until both power and phase stabilize.|功率看起來平滑就表示模態數足夠~Smooth power curves prove sufficient modes
檢查網格與對稱邊界~Check mesh and symmetry boundaries|不適用的對稱邊界會排除真實模式或端口；較細網格也不能修正錯誤物理邊界。~An invalid symmetry boundary excludes real modes or ports; finer mesh cannot fix it.|以完整幾何與放寬對稱的模型交叉比較。~Cross-check full geometry against symmetry-restricted models.|細網格可以補救錯誤對稱設定~Fine mesh compensates incorrect symmetry
量測不平衡~Measure imbalance|不平衡比較兩路可用模態功率，兩路同時低傳輸仍可能非常平衡。~Imbalance compares useful modal powers; two weak outputs can still be perfectly balanced.|同時畫總傳輸與兩路比值，解讀 0.193 dB 範例。~Plot total transmission and output ratio together and interpret the 0.193 dB example.|平衡良好就代表損耗低~Good balance implies low loss
保存相對相位~Preserve relative phase|後段干涉取決於複數振幅，只有功率的模型無法預測合光消光。~Downstream interference depends on complex amplitudes; power-only models cannot predict extinction.|比較同功率但相位差不同的兩組輸出進入合光器。~Compare equal-power outputs with different relative phases in a combiner.|兩路功率相同即可忽略相位~Equal output powers make phase irrelevant
驗證寬頻響應~Verify broadband response|模態色散使最佳成像長度隨波長改變，快速掃描近似需與完整解比較。~Modal dispersion changes imaging with wavelength; fast sweep approximations need full-solution checks.|在頻帶邊緣以獨立完整計算核對功率和相位。~Cross-check power and phase at band edges using independent full solves.|一個波長的最佳長度適用所有波長~One optimum length applies to all wavelengths
估計幾何角點~Estimate geometry corners|寬度與厚度改變模式間拍長，可能使平衡偏離而非僅增加共同損耗。~Width and thickness alter modal beat lengths and can shift balance, not just common loss.|掃共同線寬偏差並追蹤兩路不對稱。~Sweep common width bias while tracking output asymmetry.|製程偏差只能改變總損耗~Fabrication bias only changes total loss
匯出多模 S 參數~Export multimode S-parameters|每個端口與偏振都需明確編號，且複數參考面影響相位。~Every port and polarization needs explicit numbering, and reference planes affect phase.|以單一端口注入重建每一欄 S 參數並核對能量。~Excite one port/mode at a time to reconstruct columns and check energy.|S 參數只是一份與端口順序無關的功率表~S-parameters are a port-order-independent power table
驗證電路層重建~Verify circuit-level reconstruction|元件模型插入電路後應重現獨立元件的波長響應，群延遲也需一致。~An imported circuit model should reproduce standalone spectral response and group delay.|重建 MMI 頻譜並比對兩輸出複數響應及延遲。~Reconstruct spectra and compare complex outputs and delay.|模型成功匯入就代表物理結果正確~Successful model import proves physical correctness
''')
add(161,'倏逝耦合、超模拍頻與製程容差~Evanescent coupling, supermode beating and fabrication tolerance','超模與耦合~Supermodes and coupling|幾何與製程~Geometry and fabrication|頻譜與判別~Spectra and diagnosis|模型與交付~Models and handoff','假設無損對稱雙波導的超模傳播常數差 Δβ=0.04 μm⁻¹，κ=Δβ/2=0.02 μm⁻¹。交叉功率 sin²(κL)，第一次全轉移長度 π/Δβ=78.54 μm，第一次均分長度 π/(2Δβ)=39.27 μm；完整拍長 2π/Δβ=157.08 μm。~For hypothetical lossless symmetric guides, supermode difference Δβ=0.04 μm⁻¹ gives κ=0.02 μm⁻¹. Cross power is sin²(κL); first full transfer is at 78.54 μm, first equal split at 39.27 μm, and full beat length is 157.08 μm.','簡式假設相同單模波導、固定耦合係數與無損；彎曲入口、非對稱、色散及輻射需另建模。~The reduced equation assumes identical single-mode guides, constant coupling and no loss; bends, asymmetry, dispersion and radiation need separate treatment.','dc mmi',[
('a160','可共用端口功率、相位及過量損耗的量測定義~Port power, phase and excess-loss definitions transfer','兩波導耦合長度依間距，MMI 依多模區自成像~Two-guide coupling length depends on gap; MMI relies on multimode self-imaging','比較相同分光比~Compare identical split ratios|掃共同寬度偏差~Sweep shared width bias|比較頻帶平衡~Compare balance across a band'),
('a163','微環的總線—環間能量交換使用耦合器模型~Bus-ring energy exchange uses a coupler model','環形腔還有回程相位與內部損耗，不是單次傳輸~A ring also has round-trip phase and internal loss, not just one pass','提取振幅耦合係數~Extract amplitude coupling|加入環回程損耗~Add ring round-trip loss|區分欠耦合與過耦合~Distinguish under/overcoupling')],r'''
定義波導與間隙~Define guides and gap|耦合由倏逝場重疊決定，間隙是側壁之間距離而非中心距離。~Coupling follows evanescent-field overlap; gap means sidewall spacing, not center spacing.|在截面圖分開寬度、中心距和側壁間距。~Mark width, center spacing and sidewall gap separately.|中心距和間隙可以互換使用~Center spacing and gap are interchangeable
求解偶奇超模~Solve even and odd supermodes|對稱雙波導形成偶奇超模，其傳播常數差控制功率交換。~Symmetric guides form even/odd supermodes whose propagation-constant difference controls transfer.|比較兩個超模場形與有效折射率差。~Compare supermode fields and effective-index difference.|只有孤立波導折射率就足以確定耦合~Isolated-guide index alone determines coupling
核對三種長度~Distinguish three length scales|第一次均分、全轉移和完整拍長相差固定倍數，名稱混用會產生兩倍錯誤。~First equal split, full transfer and full beat length differ by fixed factors; confusing them causes factor-two errors.|重算 39.27、78.54、157.08 μm 並畫功率隨長度。~Recalculate the three lengths and plot power versus length.|拍長就是第一次全轉移長度~Beat length equals first full-transfer length
分析間隙敏感度~Analyze gap sensitivity|間隙改變場重疊及耦合係數，窄間隙的尺寸變化可能有強烈影響。~Gap changes overlap and coupling; small dimensional changes can strongly affect narrow gaps.|掃三個間隙並比較最佳長度和均分偏差。~Sweep three gaps and compare optimum length and imbalance.|耦合長度只由總波導長度決定~Coupling is determined only by total guide length
分離共同與差動線寬~Separate common and differential width bias|共同線寬偏差改變超模；差動偏差還造成兩臂相位失配，限制最大轉移。~Common width bias changes supermodes; differential bias also phase-mismatches arms and limits maximum transfer.|比較同加寬與一寬一窄的長度掃描峰值。~Compare peak transfer for common and opposite width shifts.|只要延長就能補償任意相位失配~Extra length compensates any phase mismatch
追蹤蝕刻與側壁~Track etch and sidewalls|蝕刻深度與側壁角共同改變有效截面和散射；上表面寬度不足以描述。~Etch depth and sidewall angle change effective cross-section and scattering; top width alone is insufficient.|用截面而非僅俯視尺寸建立角點模型。~Build corner models from cross-sections rather than top-view widths alone.|俯視寬度合格即可排除製程影響~Correct top-view width rules out fabrication effects
納入接近與離開區~Include approach and departure sections|兩波導在彎曲接近時已開始耦合，直段長度不是全部相互作用長度。~Coupling starts in approach bends, so the straight section is not the entire interaction.|比較只含直段與含 S 彎的模態傳輸。~Compare straight-only transfer with the full S-bend geometry.|只有平行直段才會產生耦合~Only the parallel straight section couples
測量波長依賴~Measure wavelength dependence|模式侷限和超模差隨波長改變，單波長均分器可在頻帶邊緣失衡。~Confinement and supermode splitting vary with wavelength, causing band-edge imbalance.|同步量交叉與直通頻譜，核對兩路和。~Measure cross and through spectra together and check their sum.|中心波長均分即代表寬頻均分~A center-wavelength equal split guarantees broadband balance
區分損耗與失配~Separate loss from mismatch|失配可能使光留在直通端；只有交叉功率低不能證明吸收或散射。~Mismatch can leave light in the through port; low cross power alone does not prove loss.|測量兩輸出與回反，對比總傳輸和分光比。~Measure both outputs and reflection; compare total transmission and ratio.|交叉端少掉的功率全部被吸收~All missing cross-port power is absorbed
保存耦合相位~Preserve coupling phase|無損耦合器的複數振幅關係受能量守恆約束，功率平方根不包含相位。~Lossless complex amplitudes obey energy conservation; square roots of powers omit phase.|將提取的矩陣用於雙臂干涉測試，檢查能量守恆。~Use the extracted matrix in an interference test and check energy conservation.|將功率開根號即可取得完整振幅係數~Square-root power gives the complete complex coefficient
建立製程監控結構~Build process-monitor structures|不同耦合長度的陣列可估超模差及損耗，但需控制各測試路徑耦入差異。~A length array can estimate splitting and loss, provided access-coupling differences are controlled.|用共同參考路徑正規化，再擬合整組長度資料。~Normalize to common references before fitting the length series.|單一耦合器就能唯一反推出所有製程偏差~One coupler uniquely determines all fabrication errors
交付有效模型範圍~Deliver model validity bounds|電路模型需標示波長、偏振、溫度與幾何角點；外推可能破壞物理一致性。~Circuit models need wavelength, polarization, temperature and geometry bounds; extrapolation can violate physical consistency.|在模型邊界重建場解並檢查反射、功率和相位。~Reconstruct field solutions at model bounds and check reflection, power and phase.|可插值模型可無限制外推~An interpolating model can be extrapolated without limits
''')
add(162,'MZI 相位—強度轉換、偏壓與行波電極~MZI phase-to-intensity conversion, bias and traveling-wave electrodes','干涉與基準~Interference and references|相移與偏壓~Phase and bias|高速與封裝~High speed and packaging|驗證與模型~Verification and models','假設無損平衡 MZI 的單臂 Δn_eff=10⁻⁴、L=1 mm、λ=1550 nm，Δφ=2πΔn_effL/λ=0.4054 rad。由亮態偏移時正規化輸出 cos²(Δφ/2)=0.9595；單臂 π 相移需 Δn_eff=λ/(2L)=7.75×10⁻⁴。~For a hypothetical balanced lossless MZI, one-arm Δn_eff=10⁻⁴, L=1 mm and λ=1550 nm give Δφ=0.4054 rad. Moving from the bright state gives normalized output cos²(Δφ/2)=0.9595; a one-arm π shift needs Δn_eff=7.75×10⁻⁴.','此算例不含兩臂損耗、分光失衡、電極傳輸或載子吸收；亮態附近響應不等於正交偏壓的小訊號響應。~The example omits arm loss, splitter imbalance, electrode propagation and carrier absorption; bright-state response differs from small-signal response at quadrature.','mzi tw mmi',[
('a167','載子耗盡造成的複數有效折射率可轉成 MZI 臂相移與損耗~Depletion-induced complex index maps into MZI arm phase and loss','單一相移器沒有分合光與雙臂偏壓問題~A phase shifter alone lacks splitter/combiner and two-arm bias issues','由 Δn 算相位~Convert Δn to phase|加入吸收差~Add absorption imbalance|比較推挽與單臂~Compare push-pull and single-arm drive'),
('a163','兩者都利用相位變化轉換輸出功率~Both convert phase changes into output power','微環有共振儲能與線寬，MZI 主要由兩路干涉~Rings have resonant storage and linewidth; MZIs mainly use two-path interference','比較相同 Δn~Compare equal Δn|畫波長敏感度~Plot wavelength sensitivity|比較溫控需求~Compare thermal-control requirements')],r'''
定義兩臂與端口~Define arms and ports|輸出是兩臂複數電場相加，能量會分配至互補端口；不能只加功率。~Output adds complex arm fields and distributes energy to complementary ports; powers alone cannot describe it.|以零相位與 π 相位畫兩端口功率並核對守恆。~Plot both-port powers at zero and π phase and check conservation.|兩臂功率相加就能預測干涉~Adding arm powers predicts interference
建立相位積分~Build the phase integral|不均勻相移需積分 Δn_eff(z)，只有均勻時能直接用 Δn_effL。~Nonuniform phase requires integrating Δn_eff(z); only a uniform arm reduces to Δn_effL.|比較兩段不同折射率與均勻平均的積分結果。~Compare a two-section index profile with its length-weighted mean.|任意局部最大折射率乘總長就是相位~Peak local index times total length gives phase
驗算亮態響應~Calculate bright-state response|亮態附近強度的一階斜率為零，小相位主要產生二階功率改變。~The intensity slope vanishes at the bright state; small phase causes mainly second-order power change.|重算 0.4054 rad 和 0.9595，再比較正交偏壓。~Recalculate 0.4054 rad and 0.9595, then compare quadrature bias.|亮態是最大線性小訊號靈敏度點~The bright state has maximum linear small-signal sensitivity
設定正交偏壓~Set quadrature bias|兩臂差相位約 π/2 時局部強度斜率大，但偏壓需隨溫度和波長校正。~Near π/2 differential phase the local intensity slope is large, but bias needs thermal/spectral calibration.|量完整傳輸曲線並用兩側斜率確認偏壓點。~Measure a full transfer curve and verify bias using slopes on both sides.|固定電壓永遠對應正交偏壓~A fixed voltage always gives quadrature
比較單臂與推挽~Compare single-arm and push-pull drive|相反兩臂相移增加差動相位；其共同相位和啁啾與單臂驅動不同。~Opposite arm shifts increase differential phase; common phase and chirp differ from single-arm drive.|在相同每臂相移下比較差動與共同相位。~Compare differential and common phase for equal per-arm phase shifts.|推挽只改變電壓接線不影響光學相位~Push-pull changes wiring but not optical phase
納入臂損耗差~Include arm-loss mismatch|破壞性干涉需振幅相等；即使差相位恰為 π，損耗不同仍留下殘餘光。~Destructive interference requires equal amplitudes; loss mismatch leaves residual light even at π phase.|用兩種臂振幅算最小與最大輸出，核對消光。~Calculate extrema for two arm amplitudes and check extinction.|π 相位差必然得到零輸出~A π difference always produces zero output
分析 RF 與光速度~Analyze RF and optical velocities|行波電極的調變累積受微波相速與光群速失配限制，不能只看直流 Vπ。~Traveling-wave accumulation is limited by RF phase versus optical group velocity mismatch, not only DC Vπ.|比較不同長度的電光頻率響應及延遲。~Compare electro-optic frequency response and delay for different lengths.|直流效率最高的長電極必定最高速~The most efficient long DC electrode is always fastest
檢查阻抗與終端~Check impedance and termination|電極阻抗與驅動／終端不匹配會反射並產生頻率紋波。~Mismatch between electrode, driver and termination causes reflections and frequency ripple.|量 RF S11/S21 並對照電光響應中的波紋位置。~Measure RF S11/S21 and compare ripple with electro-optic response.|光學曲線波紋一定來自光學腔~Optical-response ripple always comes from an optical cavity
追蹤熱漂與串擾~Track thermal drift and crosstalk|鄰近熱源改變兩臂差相位；共同升溫也可因不對稱轉為偏壓漂移。~Nearby heat alters differential phase; common heating can shift bias in an asymmetric device.|加熱一側鄰近器件並記錄偏壓與功率變化。~Heat a neighboring device on one side and record bias and power shifts.|共同溫升不會影響任何 MZI~Common heating cannot affect any MZI
分離電極與封裝頻寬~Separate electrode and package bandwidth|焊線、焊墊和驅動端口會加入寄生，封裝後頻寬不等於裸晶片模擬。~Bonds, pads and driver ports add parasitics; packaged bandwidth differs from bare-device simulation.|比較去嵌前後的電氣與電光頻譜。~Compare electrical/electro-optical spectra before and after de-embedding.|裸晶片頻寬就是封裝後頻寬~Bare-chip bandwidth equals packaged bandwidth
評估資料眼圖~Assess data eyes|靜態消光和小訊號頻寬都不足以單獨預測含驅動失真與噪聲的資料眼。~Static extinction and small-signal bandwidth alone do not determine a data eye with driver distortion and noise.|固定偏壓比較兩種資料速率與輸入擺幅的眼圖。~At fixed bias compare eyes at two data rates and drive swings.|最大消光比必然給最低資料錯誤率~Maximum extinction always gives minimum error rate
交付偏壓相依模型~Deliver a bias-dependent model|有效模型需保存複數折射率、電容、電阻、電極傳輸和偏壓範圍。~A useful model includes complex index, capacitance, resistance, electrode propagation and bias bounds.|用獨立偏壓點驗證模型預測，而非只重播擬合資料。~Validate at independent bias points rather than replaying fitted data.|吻合一個偏壓即可證明全範圍模型~Matching one bias validates the entire range
''')
add(163,'微環共振、耦合條件、線寬與調變漂移~Ring resonance, coupling conditions, linewidth and modulation drift','共振與尺度~Resonance and scales|耦合與損耗~Coupling and loss|調變與漂移~Modulation and drift|系統控制~System control','假設 r=10 μm、n_g=4、λ=1550 nm，周長 62.832 μm，局部 FSR≈λ²/(n_g·2πr)=9.559 nm。載入 Q=10000 對應線寬 λ/Q=0.155 nm；假想漂移係數 80 pm/K、升溫 2 K 造成 0.160 nm 位移，約一個線寬。~For hypothetical r=10 μm, n_g=4 and λ=1550 nm, circumference is 62.832 μm and local FSR≈9.559 nm. Loaded Q=10000 gives 0.155 nm linewidth. An assumed 80 pm/K drift over 2 K shifts resonance 0.160 nm, about one linewidth.','FSR 用群折射率，Q 為載入值；局部波長近似不涵蓋跨大頻帶色散。漂移係數自行設定，不是所有矽微環的材料常數。~FSR uses group index and Q is loaded; the local wavelength approximation omits broad-band dispersion. The chosen drift coefficient is not universal for silicon rings.','ring dc tw',[
('a161','環與總線間的耦合係數可由雙波導超模求得~Bus-ring coupling can be derived from two-guide supermodes','直耦合器不含環腔回程干涉與光子壽命~A straight coupler lacks ring round-trip interference and photon lifetime','取耦合矩陣~Extract the coupling matrix|加入回程相位~Add round-trip phase|掃內損耗與耦合~Sweep internal loss and coupling'),
('a166','加熱造成的相位變化可用於微環波長調諧~Thermal phase change tunes ring wavelength','熱調諧頻寬與高速載子調變不同~Thermal tuning bandwidth differs from fast carrier modulation','量熱調諧斜率~Measure thermal tuning slope|算一個線寬的功率~Calculate power for a linewidth|比較熱與資料時間尺度~Compare thermal and data timescales')],r'''
建立回程相位~Establish round-trip phase|共振要求回程相位為整數 2π，幾何周長與有效折射率共同決定位置。~Resonance requires integer-2π round-trip phase, set jointly by circumference and effective index.|比較加長環與增加有效折射率造成的共振移動。~Compare resonance shifts from longer circumference and higher effective index.|只要半徑相同共振波長一定相同~Equal radii guarantee equal resonance wavelengths
區分相位與群折射率~Separate phase and group indices|相位指標決定特定模式條件，頻率間隔由群延遲決定而使用 n_g。~Phase index sets individual resonance conditions; spectral spacing follows group delay and uses n_g.|由相鄰共振間隔反推 n_g，與相位指標分列。~Infer n_g from adjacent resonances and list it separately from phase index.|FSR 公式可任意把 n_g 換成 n_eff~n_g and n_eff are interchangeable in FSR
驗算 FSR 與線寬~Calculate FSR and linewidth|FSR 是相鄰共振間隔，線寬是一個共振的寬度，兩者不能混稱頻寬。~FSR separates resonances; linewidth describes one resonance, so the two are not interchangeable bandwidths.|重算 9.559 nm 與 0.155 nm，再求精細度約 61.7。~Recalculate 9.559 and 0.155 nm, then finesse about 61.7.|FSR 等於每個共振的線寬~FSR equals each resonance linewidth
區分載入與內部 Q~Separate loaded and intrinsic Q|載入損耗包含內部與耦合通道，1/Q_loaded=1/Q_internal+1/Q_coupling。~Loaded decay includes intrinsic and coupling channels, with inverse Q values adding.|比較同一內損耗下不同耦合強度的線寬。~Compare linewidth for different coupling at fixed intrinsic loss.|量到的載入 Q 就是材料本身 Q~Measured loaded Q equals material Q
判讀臨界耦合~Interpret critical coupling|全通環在耦合流出與內部損耗匹配時可有深凹口，但深凹口不是無損。~An all-pass ring can notch deeply when coupling escape matches internal loss; a deep notch does not imply losslessness.|同時擬合凹口深度、線寬和相位以區分耦合情況。~Fit notch depth, width and phase jointly to distinguish coupling regimes.|最深凹口必然來自最低內部損耗~The deepest notch always means lowest intrinsic loss
檢查背向散射分裂~Check backscatter splitting|側壁散射可耦合順逆行模式造成共振分裂，單 Lorentzian 擬合可能失準。~Sidewall scattering can couple counterpropagating modes and split a resonance, invalidating a single-Lorentzian fit.|提高頻譜解析度比較單峰與雙峰模型殘差。~Increase spectral resolution and compare single/double-peak residuals.|雙峰一定代表兩個不同大小的環~A doublet always means two different rings
選擇調變工作點~Choose a modulation operating point|載子引起的共振位移在斜坡轉為功率變化；中心點與斜坡點靈敏度不同。~Carrier-induced resonance shifts become intensity change on a slope; center and slope points differ in sensitivity.|在固定雷射波長比較三個偏壓位置的動態響應。~Compare dynamic response at three bias positions with fixed laser wavelength.|共振最深點一定是最高線性調變效率~The deepest point always maximizes linear modulation efficiency
評估光子壽命~Assess photon lifetime|提高 Q 縮窄線寬並增加儲能時間，會與高速調變需求形成取捨。~Higher Q narrows linewidth and lengthens energy storage, trading against modulation speed.|比較不同 Q 的階躍響應與穩態斜率。~Compare step responses and steady slopes for different Q values.|Q 越高就能無限制增加資料速率~Higher Q permits unlimited data-rate improvement
量化溫度漂移~Quantify thermal drift|溫漂應以線寬或允許失諧正規化，固定 nm 位移對不同 Q 影響不同。~Normalize thermal drift to linewidth or detuning allowance; equal nm shifts affect different Q differently.|比較 0.160 nm 位移對 Q=10000 與 5000 的線寬比例。~Compare a 0.160 nm shift against linewidths at Q=10000 and 5000.|相同波長漂移對所有 Q 有相同影響~Equal wavelength drift affects every Q identically
檢查功率自熱~Check optical self-heating|吸收可產生局部升溫並反過來移動共振，掃描方向和功率可能改變峰形。~Absorption heats the ring and shifts resonance, making lineshapes power- and scan-direction-dependent.|降低輸入功率並反向掃波長，查看遲滯是否減弱。~Reduce input power and reverse the wavelength sweep to test hysteresis.|頻譜隨掃描方向變化一定是儀器故障~Scan-direction dependence always means instrument failure
建立鎖定與串擾控制~Establish locking and crosstalk control|多環系統的加熱器互相耦合，獨立單環校準不足以描述共同工作。~Heaters interact in multiring systems; isolated calibrations do not describe simultaneous operation.|建立加熱功率對多個共振位移的矩陣。~Build a heater-power versus resonance-shift matrix.|每個環單獨校正即可消除所有串擾~Separate ring calibration removes every crosstalk effect
交付頻譜與調變證據~Deliver spectral and modulation evidence|交付需同時保留 FSR、線寬、耦合、漂移和偏壓動態，單一 Q 不能代表調變器品質。~Deliver FSR, linewidth, coupling, drift and biased dynamics; one Q does not characterize a modulator.|以獨立溫度和輸入功率條件檢驗模型外推。~Test predictions at independent temperature and input-power conditions.|最高 Q 的樣品必定是最佳調變器~The highest-Q sample must be the best modulator
''')
add(164,'Ge 吸收、載子收集與光電量測基準~Ge absorption, carrier collection and optoelectronic reference planes','光與材料~Light and material|接面與輸運~Junctions and transport|響應與頻寬~Response and bandwidth|封裝與驗證~Packaging and verification','假設 1550 nm 光、外部量子效率 η=0.80（以指定晶片端口功率為基準），R=ηqλ/(hc)≈ηλ(μm)/1.23984=1.000 A/W。100 μW 入射產生約 100 μA 光電流；若暗電流 1 μA，總讀值約 101 μA，計算 R 前需扣除暗值。~For hypothetical 1550 nm light and external quantum efficiency 0.80 referenced to a defined chip port, R=ηqλ/(hc)≈1.000 A/W. A 100 μW input gives about 100 μA photocurrent; with 1 μA dark current the total is about 101 μA, requiring dark subtraction.','外部量子效率已包含所定參考面到收集電流的損失；內部效率、吸收比例與封裝入射功率不可混用。~External efficiency includes losses between the defined reference plane and collected current; internal efficiency, absorption fraction and package-input power must not be conflated.','pd apd',[
('a165','吸收、暗電流與載子收集可作 APD 的基線~Absorption, dark current and carrier collection establish an APD baseline','APD 另有乘增、過量噪聲與高場管理~An APD adds multiplication, excess noise and high-field management','建立單位增益響應~Establish unity-gain response|扣除暗電流~Subtract dark current|比較增益與噪聲~Compare gain and noise'),
('a178','相干接收器需以匹配響應度與電容連接平衡 TIA~Coherent receivers connect matched responsivity and capacitance to balanced TIAs','單一 Ge 偵測器不含光混頻、本地振盪器與平衡通道~One Ge detector does not include an optical hybrid, local oscillator or balanced channels','計算入射光電流~Calculate input photocurrent|加入 TIA 噪聲~Add TIA noise|比較兩個功率基準~Compare two power reference planes')],r'''
定義吸收區與光路~Define absorber and optical path|矽波導把光模態引入 Ge 吸收區，重疊與長度共同決定吸收。~A silicon guide delivers a mode to the Ge absorber; overlap and length jointly set absorption.|畫模態在 Ge 與 Si 的分布，分開耦入與吸收損失。~Map the mode in Ge/Si and separate coupling from absorption loss.|只要有 Ge 就能吸收所有入射光~Any Ge region absorbs all incident light
檢查材料缺陷~Check material defects|Ge/Si 材料界面與缺陷可能提供復合或漏電通道；光吸收良好不代表低暗電流。~Ge/Si interfaces and defects may create recombination or leakage paths; good absorption does not ensure low dark current.|對照材料影像、暗電流與光響應，避免只用單一光譜判定。~Correlate material images, dark current and photoresponse.|吸收強就能保證材料低缺陷~Strong absorption guarantees low-defect material
驗算量子效率~Calculate quantum efficiency|每個被收集光子產生的電荷把功率轉為電流，響應度的 A/W 依波長改變。~Collected charge per photon converts optical power to current, so A/W responsivity depends on wavelength.|重算 1.000 A/W 並檢查是否使用 μm 而非 nm 代入簡式。~Recalculate 1.000 A/W and check μm versus nm in the reduced formula.|相同量子效率在所有波長都有相同 A/W~Equal quantum efficiency gives equal A/W at all wavelengths
辨識電場與耗盡~Identify field and depletion|反向偏壓可增加收集場與耗盡範圍，但也可能提高漏電或接近擊穿。~Reverse bias can strengthen collection fields/depletion but also leakage or breakdown risk.|比較暗／亮 I–V 與電容曲線，找收集改善是否飽和。~Compare dark/light I–V and capacitance to see whether collection improvement saturates.|反向偏壓越高永遠越好~Higher reverse bias is always better
計算載子收集~Analyze carrier collection|吸收產生的載子可能先復合才被電极收集，吸收效率不等於收集效率。~Photocarriers can recombine before collection, so absorption and collection efficiencies differ.|比較光生成分布與電流密度，標出低場滯留區。~Compare photogeneration with current density and identify low-field regions.|吸收一個光子必定得到一個收集電子~Each absorbed photon guarantees one collected electron
分離暗電流路徑~Separate dark-current paths|接面體積與表面／周邊漏電可有不同尺寸尺度，總暗電流不能直接辨識缺陷類型。~Bulk and surface/perimeter leakage scale differently; total dark current alone does not identify defects.|比較不同面積與周長器件並在相同偏壓溫度正規化。~Compare area/perimeter variants at common bias and temperature.|所有暗電流都正比於器件面積~All dark current scales with device area
校準功率參考面~Calibrate the power reference plane|纖維端功率與探測器端功率相差耦合和路徑損耗，需明示去嵌範圍。~Fiber-input and detector-input power differ by coupling/path losses; state de-embedding boundaries.|以參考波導量耦入損失，再分别報外部與去嵌響應。~Use a reference guide to assess coupling and report external/de-embedded response separately.|功率計讀值可直接當吸收區入射功率~Power-meter readings directly equal absorber input power
確認線性與飽和~Confirm linearity and saturation|高光功率的空間電荷、電路限流或自熱可壓縮響應，暗扣除不足以修正。~Space charge, circuit current limits or heating can compress high-power response; dark subtraction cannot fix it.|掃輸入功率並看增量斜率，而非只看總電流。~Sweep optical input and inspect incremental slope, not only total current.|扣除暗電流後響應必定線性~Dark subtraction guarantees linear response
拆分 RC 與渡越時間~Separate RC and transit time|電容／電阻和載子穿越時間都可能限制頻寬；縮短吸收區會改變吸收與電容。~Resistance-capacitance and carrier transit both limit bandwidth; shortening the absorber changes absorption and capacitance.|比較幾何變化的 C–V、頻率響應與響應度。~Compare C–V, frequency response and responsivity for geometry variants.|降低電容就能無限制增加頻寬~Reducing capacitance allows unlimited bandwidth
檢查接觸與封裝寄生~Check contacts and package parasitics|接觸阻抗、焊墊和連線使量得頻寬包含外部路徑，須分清器件與治具。~Contacts, pads and interconnects make measured bandwidth include external paths.|比較校準結構與器件的 S 參數，記錄去嵌不確定度。~Compare calibration structures and device S-parameters and retain de-embedding uncertainty.|去嵌後數據沒有任何不確定度~De-embedded data have no uncertainty
評估噪聲與溫度~Assess noise and temperature|暗電流、散粒噪聲與讀出噪聲隨條件改變，低暗值不等於最低系統噪聲。~Dark current, shot noise and readout noise vary with conditions; low dark current does not ensure minimum system noise.|分別測暗態噪聲、受光噪聲及電子背景，保持相同頻寬。~Measure dark, illuminated and electronic noise at common bandwidth.|只知道暗電流就能算出全部接收噪聲~Dark current alone determines all receiver noise
交付光電模型~Deliver an optoelectronic model|交付需有參考面、波長、偏壓、溫度、響應度、暗值和頻寬，不能只報最大 A/W。~Deliver reference plane, wavelength, bias, temperature, responsivity, dark current and bandwidth, not just peak A/W.|以獨立功率與溫度點驗證電流及頻率預測。~Validate current and frequency predictions at independent power/temperature points.|最大響應度就是完整探測器規格~Maximum responsivity is a complete detector specification
''')
source('apdnoise','APD 增益與過量噪聲技術說明~APD gain and excess-noise technical note','Hamamatsu Photonics','https://www.hamamatsu.com/content/dam/hamamatsu-photonics/sites/documents/99_SALES_LIBRARY/ssd/si-apd_kapd9007e.pdf','原廠電子注入 McIntyre 型局部噪聲關係；不是 Ge/Si 特定器件參數。~Vendor electron-injection McIntyre-type local-noise relation, not parameters of a specific Ge/Si device.')
add(165,'Ge 吸收／Si 乘增分工、增益與過量噪聲~Ge absorption/Si multiplication, gain and excess noise','吸收與高場~Absorption and high field|增益與噪聲~Gain and noise|動態與溫控~Dynamics and temperature control|接收器驗證~Receiver verification','假想單位增益光電流 I₀=5 μA、M=10，平均乘增光電流 50 μA。電子注入局部模型取 k=β/α=0.10（電洞／電子游離係數比），F=kM+(1−k)(2−1/M)=2.71；初級光電流散粒噪聲的單邊功率譜密度為 2qI₀M²F，不是只乘 M。~For hypothetical unity-gain photocurrent I₀=5 μA and M=10, mean multiplied current is 50 μA. An electron-injection local model with k=β/α=0.10 (hole/electron ionization ratio) gives F=kM+(1−k)(2−1/M)=2.71. Primary photocurrent shot-noise one-sided PSD is 2qI₀M²F, not merely multiplied by M.','此例採線性模式、均勻局部游離與電子注入近似；薄乘增層的非局部效應、混合注入、暗電流和電路噪聲另算。提高平均增益不能單獨證明 SNR 改善。~This assumes linear mode, uniform local ionization and electron injection. Nonlocal effects in thin multiplication regions, mixed injection, dark current and circuit noise are separate. Mean gain alone does not establish improved SNR.','apd apd09 apdnoise pd',[
('a164','Ge 吸收及未乘增響應度是 APD 增益計算基準~Ge absorption and unity-gain responsivity define the APD gain reference','普通光二極體不含雪崩建立時間與乘增噪聲~A regular photodiode lacks avalanche buildup and multiplication noise','取得低場光電流~Measure low-field photocurrent|追蹤收集效率變化~Track collection-efficiency change|再計算真實增益~Then calculate multiplication gain'),
('a193','接收鏈路需將 APD 增益與 TIA 噪聲一起評估~Receiver design evaluates APD gain jointly with TIA noise','器件增益最大點未必是系統靈敏度最佳點~Maximum device gain need not maximize receiver sensitivity','列出各噪聲來源~List noise contributions|掃增益算 SNR~Sweep gain and calculate SNR|比較飽和與頻寬~Compare saturation and bandwidth')],r'''
劃分吸收與乘增區~Separate absorption and multiplication regions|Ge 可負責長波長吸收，Si 乘增區提供合適高場；兩區電場需求不同。~Ge can absorb long-wavelength light while Si supplies multiplication; their field requirements differ.|畫材料、光生成與高場位置，核對載子走向。~Map materials, photogeneration and high field and check carrier travel.|吸收與乘增必須在同一材料同一位置~Absorption and multiplication must occur at one material/location
檢查電場配置~Check field distribution|乘增區需要高場，但吸收區過高電場可能增加穿隧或漏電，不能僅最大化峰值。~Multiplication needs high field, but excessive absorber field can increase tunneling/leakage; peak field alone is not the objective.|對照電場剖面與暗 I–V，標記局部場集中。~Compare field profiles with dark I–V and mark field crowding.|峰值電場越大 APD 品質越好~Higher peak field always means a better APD
定義單位增益基準~Define the unity-gain reference|增益應以已有效收集而尚未顯著乘增的光電流為基準，先扣各偏壓暗電流。~Gain references well-collected but minimally multiplied photocurrent after bias-specific dark subtraction.|比較低偏壓收集飽和區，避免把收集改善誤算成乘增。~Identify the low-bias collection plateau so improved collection is not mistaken for gain.|任意零偏壓電流都可當單位增益基準~Any zero-bias current is a unity-gain reference
區分線性與 Geiger 模式~Distinguish linear and Geiger operation|線性 APD 在擊穿以下以平均增益讀出；Geiger 模式事件需淬熄與計數描述。~A linear APD uses mean gain below breakdown; Geiger operation needs quenching and event counting.|分別列出連續電流與單次脈衝所需讀出模型。~List readout models for continuous current versus individual pulses.|線性 APD 可以直接套用單光子計數規格~Linear APDs directly inherit single-photon counting specifications
驗算乘增平均值~Calculate mean multiplication|平均輸出光電流為 M 倍初級光電流，但暗路徑可能有不同乘增比例。~Mean photocurrent is M times primary current, while dark paths can multiply differently.|重算 5 μA 到 50 μA，分開體內與表面暗值。~Recalculate 5 to 50 μA and separate bulk/surface dark current.|總暗電流都必定乘上同一 M~All dark current necessarily multiplies by the same M
分析過量噪聲~Analyze excess noise|雪崩隨機性使電流變異大於確定性增益，電子注入的 k 定義不能反轉。~Avalanche randomness adds variance beyond deterministic gain; preserve the electron-injection definition of k.|重算 F=2.71，並比較 k=0 與 k=1 的極限。~Recalculate F=2.71 and compare k=0 and k=1 limits.|F=2.71 表示平均電流只增益 2.71 倍~F=2.71 means mean current gain is 2.71
建立完整噪聲預算~Build a full noise budget|初級散粒噪聲按 M²F 進入功率譜，外部放大器噪聲並不都經 APD 乘增。~Primary shot-noise PSD scales by M²F; external amplifier noise is not all multiplied by the APD.|在相同噪聲頻寬比較低增益和高增益的總 SNR。~Compare total SNR at low/high gain using the same noise bandwidth.|信號增加十倍就表示 SNR 增加十倍~Tenfold signal always means tenfold SNR
評估雪崩建立時間~Assess avalanche buildup time|多次游離需要時間，增益提高可降低有效頻寬，還需加上渡越和 RC 限制。~Repeated ionization takes time; increased gain can reduce bandwidth in addition to transit and RC limits.|量增益對頻寬曲線，分離低增益時已存在的限制。~Measure gain versus bandwidth and identify preexisting low-gain limits.|APD 增益和速度彼此完全獨立~APD gain and speed are independent
辨識溫度與擊穿漂移~Identify thermal and breakdown drift|游離率與擊穿條件隨溫度變動，固定電壓不等於固定增益。~Ionization and breakdown conditions vary with temperature; fixed voltage does not ensure fixed gain.|在兩個溫度量暗／亮 I–V 並建立增益控制圖。~Measure dark/light I–V at two temperatures and map gain control.|固定供電可保證各溫度相同增益~Fixed supply guarantees equal gain at every temperature
檢查邊緣提前擊穿~Check premature edge breakdown|接面邊緣場集中可能在主動區之前擊穿，總 I–V 需與位置資訊合看。~Junction-edge crowding can break down before the active region; combine I–V with spatial evidence.|比較不同周長和邊緣設計的漏電及發光／電場圖。~Compare leakage and emission/field maps for perimeter/edge variants.|任何擊穿上升都代表均勻有用乘增~Any breakdown rise indicates uniform useful multiplication
評估功率壓縮~Assess optical-power compression|高光電流的空間電荷和串聯壓降會改變乘增電場，M 可隨入光降低。~Space charge and series-voltage drop at high photocurrent alter field, making M power-dependent.|固定外部偏壓掃功率，檢查增量響應與電壓降。~Sweep power at fixed bias and inspect incremental response and voltage drop.|固定偏壓下 M 不可能隨光功率改變~M cannot depend on optical power at fixed bias
交付接收器適用性~Deliver receiver suitability evidence|APD 選型需以靈敏度、噪聲、頻寬、動態範圍及溫控共同判定。~APD selection combines sensitivity, noise, bandwidth, dynamic range and thermal control.|在同一資料速率與誤碼定義下比較數個增益工作點。~Compare gain operating points at common data rate and error definition.|最高增益樣品永遠是最佳接收器~The highest-gain sample is always the best receiver
''')
add(166,'熱光相位、熱阻／熱容與多通道串擾~Thermo-optic phase, thermal resistance/capacitance and crosstalk','熱與模態~Heat and modes|功率與效率~Power and efficiency|瞬態與串擾~Transient response and crosstalk|校準與保持~Calibration and retention','假設均勻有效熱光係數 dn_eff/dT=1.8×10⁻⁴ K⁻¹、L=1 mm、λ=1.55 μm，ΔTπ=λ/(2L·dn_eff/dT)=4.306 K。若集總 R_th=200 K/W，Pπ=21.53 mW；再假設 C_th=10 μJ/K，τ=R_thC_th=2.00 ms。~With hypothetical uniform effective dn_eff/dT=1.8×10⁻⁴ K⁻¹, L=1 mm and λ=1.55 μm, ΔTπ=4.306 K. A lumped R_th=200 K/W gives Pπ=21.53 mW; assumed C_th=10 μJ/K gives τ=2.00 ms.','係數是有效模態係數而非純材料值，溫度視為均勻；R_th、C_th 為同一集總熱節點，真實結構可能有多個時間常數及溫度相依電阻。~The coefficient is modal rather than purely material and temperature is uniform. R_th/C_th describe one lumped thermal node; real structures can have multiple time constants and temperature-dependent resistance.','heater mzi thermal',[
('a163','熱相位積分可轉成共振波長調諧~Thermal phase integration maps into resonance tuning','環的鎖定誤差要相對線寬評估，直線相移器以弧度交付~Ring lock error is relative to linewidth; a straight phase shifter delivers radians','從溫度算相位~Convert temperature to phase|映射成環失諧~Map to ring detuning|比較一個線寬的功率~Compare power for one linewidth'),
('a167','兩者以有效折射率積分產生相位~Both create phase through effective-index integration','熱光主要受熱擴散限制，耗盡型還有電容與載子吸收~Thermal phase is diffusion-limited; depletion adds capacitance and carrier absorption','保持相同 π 相移~Hold equal π shift|比較靜態功耗~Compare static power|比較時間響應~Compare response time')],r'''
定義加熱與光學區~Define heater and optical regions|加熱器位置決定熱流路徑，金屬靠近波導也可能增加光吸收。~Heater placement sets heat-flow paths, while metal near a guide can increase optical absorption.|在截面同時標電流、熱流和光模態。~Mark current, heat flow and optical mode on one cross-section.|加熱器越靠近光芯只有好處~Moving a heater closer to the optical core has only benefits
從溫度場到模態~Map temperature fields to modes|光學有效折射率受模態加權的材料溫度與應力影響，峰值溫度不是全段平均。~Modal index depends on optically weighted temperature and stress; peak temperature is not a path average.|比較均勻溫升與局部熱點的相位積分。~Compare phase integrals for uniform heating and a local hotspot.|最高溫度乘總長就能得到準確相位~Peak temperature times total length gives exact phase
驗算 π 相移溫升~Calculate temperature for π phase|均勻近似下 Δφ=2πL(dn_eff/dT)ΔT/λ，需將 mm 與 μm 換成同單位。~For uniform heating Δφ=2πL(dn_eff/dT)ΔT/λ; convert mm and μm consistently.|重算 4.306 K，並比較長度減半時所需溫升。~Recalculate 4.306 K and compare with half the length.|長度減半所需 π 相移溫升也減半~Halving length halves the required π-shift temperature
量測加熱器電阻~Measure heater resistance|實際功率來自器件端 V·I；引線壓降與溫度相依電阻可能使 V²/R 常數估計失準。~Device power is terminal V·I; lead drops and temperature-dependent resistance can invalidate constant-R V²/R estimates.|用四線或已校準引線量測比較冷熱電阻。~Use four-wire or calibrated-lead measurements to compare cold/hot resistance.|電源顯示電壓就是加熱器端電壓~Supply voltage always equals heater-terminal voltage
建立熱阻邊界~Establish thermal-resistance boundaries|熱阻 ΔT/P 取決於熱源與溫度基準及散熱邊界，不能當材料固定常數。~Thermal resistance ΔT/P depends on source/reference nodes and cooling boundaries, not just material.|把環境、晶片底面與波導溫度分開，重算 21.53 mW。~Separate ambient, die-bottom and guide temperatures and recalculate 21.53 mW.|熱阻是與封裝無關的固定材料值~Thermal resistance is a package-independent material constant
比較隔熱與效率~Compare insulation and efficiency|提高熱隔離可降低維持相移功率，但改變熱恢復、機械支撐和溫度均勻性。~Thermal isolation can reduce hold power while changing recovery, support and temperature uniformity.|比較兩種散熱邊界的 Pπ、熱圖與時間響應。~Compare Pπ, thermal maps and dynamics for two cooling boundaries.|最低 Pπ 自動等於最佳整體設計~Lowest Pπ automatically means best overall design
求集總時間常數~Calculate a lumped time constant|單節點模型有 τ=R_thC_th，熱容單位是 J/K 而非 W/K。~A single-node model gives τ=R_thC_th, with heat capacity in J/K rather than W/K.|重算 2.00 ms，並查 63.2% 階躍溫升時刻。~Recalculate 2.00 ms and check the 63.2% step-response time.|時間常數等於達到完全穩態的時間~The time constant is the time to full steady state
辨識多時間常數~Identify multiple time constants|波導、包覆與基板可能形成多熱節點，單指数擬合可能只描述部分時間。~Guide, cladding and substrate form multiple thermal nodes; one exponential may fit only part of a transient.|在短時與長時分別檢查擬合殘差，避免只取單一上升時間。~Inspect short/long-time residuals rather than relying on one rise time.|每個熱相移器都必然只有一個時間常數~Every thermal phase shifter has one time constant
測量鄰近串擾~Measure neighboring crosstalk|一個加熱器會改變多個波導相位，串擾應以多輸入多輸出矩陣表示。~One heater changes multiple guide phases; crosstalk requires a multi-input/multi-output matrix.|逐一驅動加熱器量所有相移，再核對同時驅動。~Drive heaters separately while measuring all phases, then check simultaneous drive.|各加熱器校準完就無需串擾矩陣~Individual heater calibration removes the need for crosstalk matrices
建立相位校準~Establish phase calibration|干涉輸出具有週期性，僅由單一強度讀值可能無法唯一反推相位。~Interference is periodic, so one intensity reading may not uniquely determine phase.|連續掃功率並展開相位，記錄明暗週期與分支。~Sweep power continuously, unwrap phase and record fringe branches.|同一輸出功率一定對應同一相位~Equal output power always means equal phase
追蹤漂移與材料老化~Track drift and aging|電阻漂移、界面改變與環境溫度可使舊校準失效，需分離電熱與光學來源。~Resistance drift, interface changes and ambient temperature can invalidate calibration; separate electrical, thermal and optical causes.|比較相同電功率下的溫度與相位，定位漂移來源。~Compare temperature and phase at equal electrical power to locate drift.|相位漂移一定是熱光係數改變~Phase drift always means a changed thermo-optic coefficient
交付控制模型~Deliver a control model|控制器需要功率—相位曲線、動態、串擾與工作範圍，而非只有 Pπ。~A controller needs power-phase curves, dynamics, crosstalk and bounds, not only Pπ.|以新相位目標測收斂時間、過衝與保持誤差。~Test settling, overshoot and hold error at a new phase target.|知道 Pπ 即可完成所有控制設計~Pπ alone completes control design
''')
add(167,'反向接面耗盡、複數折射率與電光限制~Reverse-junction depletion, complex index and electro-optic limits','接面與光模態~Junctions and optical modes|相位與吸收~Phase and absorption|RC 與行波~RC and traveling waves|偏壓與交付~Bias and handoff','假設已知有效折射率改變 Δn_eff=−2×10⁻⁴、L=2 mm、λ=1550 nm，單一路徑 Δφ=2πΔn_effL/λ=−1.621 rad。另取集總 R=50 Ω、C=100 fF，f_RC=1/(2πRC)=31.83 GHz；這個電氣單極估計不是整體電光頻寬。~With hypothetical known Δn_eff=−2×10⁻⁴, L=2 mm and λ=1550 nm, single-path Δφ=−1.621 rad. Separately, lumped R=50 Ω and C=100 fF give f_RC=31.83 GHz; this electrical single-pole estimate is not total electro-optic bandwidth.','Δn_eff 是自行指定的有號模態差，未由某劑量或偏壓保證；載子濃度、重疊、吸收、電容與 RF 傳輸必須以同一截面及偏壓驗證。~Δn_eff is an independently chosen signed modal difference, not guaranteed by a dose or bias. Carrier distribution, overlap, absorption, capacitance and RF propagation must be validated for the same cross-section and bias.','tw mzi',[
('a162','相移與吸收模型可直接供 MZI 雙臂模型使用~Phase and absorption models feed an MZI arm model','MZI 加上干涉偏壓與分光器，不能只看接面相移~An MZI adds interference bias and splitters, beyond junction phase alone','取得有號 Δn~Extract signed Δn|計算兩臂差相位~Calculate differential arm phase|加入臂損耗差~Add arm-loss mismatch'),
('a166','相移積分與量測方法可共用~Phase integration and measurement methods transfer','耗盡調變以反向接面調載子，熱相移以溫度調模態~Depletion changes carriers in a reverse junction; thermal phase changes modal temperature','比較相同相位目標~Compare equal phase targets|分開動態和保持功耗~Separate switching and hold power|比較熱串擾與電容負載~Compare thermal crosstalk and capacitive load')],r'''
定義接面與反向偏壓~Define junction and reverse bias|反向偏壓擴大耗盡區，改變與光模態重疊的自由載子，不是注入大量少數載子。~Reverse bias widens depletion and changes free carriers overlapping the mode, rather than injecting many minority carriers.|畫 p/n 區、電壓極性與耗盡變化方向。~Draw p/n regions, voltage polarity and depletion expansion.|耗盡調變就是正向注入載子~Depletion modulation is forward carrier injection
檢查模態重疊~Check modal overlap|相同總載子變化在不同位置產生不同 Δn_eff，需用光場權重而非只比摻雜量。~Equal carrier changes at different locations give different Δn_eff due to optical weighting, not just total dopant count.|比較接面位於模態中心與外側的有效折射率變化。~Compare junctions at the modal center and edge.|相同總摻雜量一定帶來相同調變效率~Equal total dopant count gives equal efficiency
驗算有號相移~Calculate signed phase change|Δφ 由有號有效折射率差積分得到，符號需隨同參考偏壓與臂方向保存。~Phase integrates signed modal-index change; preserve sign together with reference bias and arm convention.|重算 −1.621 rad，再反轉差值定義檢查符號。~Recalculate −1.621 rad and reverse the difference convention to check sign.|相移只有大小而無須定義符號~Phase shift needs magnitude but no sign convention
同時追蹤吸收~Track absorption alongside phase|自由載子變化會改變折射率與吸收，效率與插損不能以單一實數模型完全描述。~Carrier changes affect both index and absorption; one real-index model cannot capture efficiency and loss.|在每個偏壓提取複數模態指標及傳播損耗。~Extract complex modal index and propagation loss at each bias.|載子改變只影響相位而不影響損耗~Carrier changes affect phase but never loss
比較接面配置~Compare junction placement|橫向、垂直或交錯接面改變場重疊、電容與電阻，不能只以一個 VπL 排名。~Lateral, vertical or interleaved junctions alter overlap, capacitance and resistance; VπL alone cannot rank them.|比較相同長度下的相移、損耗與 C–V。~Compare phase, loss and C–V at equal length.|最低 VπL 的截面必定最佳~The smallest VπL cross-section is always best
量測偏壓相依電容~Measure bias-dependent capacitance|耗盡寬度隨偏壓改變，使小訊號電容也是偏壓與頻率相關量。~Bias changes depletion width, making small-signal capacitance dependent on bias and frequency.|在相同偏壓比較 C–V 與光相移斜率。~Compare C–V and optical phase slope at matching biases.|一個零偏壓電容適用所有操作偏壓~Zero-bias capacitance applies at every operating bias
界定串聯電阻~Define series resistance|接觸、摻雜導電區與驅動源共同限制充放電，需說明 R 所含邊界。~Contacts, doped access regions and the driver limit charging; define which contributions are in R.|用等效電路標出源、接觸與接面，檢查去嵌位置。~Map source, contacts and junction in the equivalent circuit and check de-embedding planes.|50 Ω 儀器介面代表元件內部電阻一定 50 Ω~A 50 Ω instrument implies a 50 Ω internal device
驗算集總 RC 頻率~Calculate lumped RC frequency|一階 RC 極點僅適用電氣上短的集總負載，不包括行波速度失配及光學儲能。~A first-order RC pole applies to an electrically short lumped load, excluding traveling-wave mismatch and optical storage.|重算 31.83 GHz，再列未納入的頻寬限制。~Recalculate 31.83 GHz and list omitted bandwidth limits.|RC 截止頻率就是任何器件的最終電光頻寬~RC cutoff is every device’s final electro-optic bandwidth
分析長度與行波~Analyze length and traveling waves|長器件可增加相移也增加損耗和分布電性，需由集總轉為傳輸線模型。~Longer devices increase phase but also loss/distributed effects, requiring transmission-line models.|比較兩種長度的直流相移與高頻電光響應。~Compare DC phase and high-frequency electro-optic response at two lengths.|把長度加倍永遠只會把效率加倍~Doubling length only doubles efficiency
區分儲能與每位元能量~Separate stored energy and energy per bit|電容儲能 ½CV² 不是通用每位元耗能；資料轉換機率、驅動架構與回收決定平均功耗。~Stored energy ½CV² is not universal energy per bit; transitions, driver architecture and recovery set average power.|列出電壓擺幅定義與資料轉換率再計功耗。~Specify swing convention and transition rate before calculating power.|½CV² 在所有驅動方式都等於每位元能量~½CV² equals energy per bit for every driver
辨識漏電與擊穿邊界~Identify leakage and breakdown bounds|反向偏壓提高可能增加效率範圍但受局部電場、漏電和可靠度限制。~Higher reverse bias may extend tuning but is constrained by field crowding, leakage and reliability.|將 I–V 異常與相位斜率變化對照，標示未驗證區。~Correlate I–V anomalies with phase-slope changes and mark unvalidated regions.|只要模擬收斂就能安全提高反向偏壓~Simulation convergence permits any higher reverse bias
交付一致偏壓模型~Deliver a consistent bias model|相移、吸收、電容與電阻必須來自相同幾何偏壓條件，混搭最佳值會失真。~Phase, absorption, capacitance and resistance must share geometry/bias conditions; combining unrelated best values distorts predictions.|用同一器件資料集預測 MZI 或微環響應並留獨立驗證點。~Predict MZI/ring response from one consistent dataset and reserve independent validation points.|可以把不同樣品的最佳數值組成一顆理想元件~Best values from different samples form a valid ideal device
''')
